add_shortcode( 'countdown', 'perfectpixel_countdown_shortcode' );

function perfectpixel_countdown_shortcode( $atts ) {
	$atts = shortcode_atts( array( 'date' => '', 'message' => '{{countdown_expired}}' ), $atts, 'countdown' );
	if ( '' === trim( $atts['date'] ) ) {
		return '';
	}
	try {
		$end = new DateTimeImmutable( trim( $atts['date'] ), wp_timezone() );
	} catch ( Exception $e ) {
		return '';
	}
	$units = array(
		'd' => '{{countdown_days}}',
		'h' => '{{countdown_hours}}',
		'm' => '{{countdown_minutes}}',
		's' => '{{countdown_seconds}}',
	);
	$html = '<div class="perfectpixel-countdown" data-end="' . esc_attr( $end->getTimestamp() * 1000 ) . '" data-expired="' . esc_attr( $atts['message'] ) . '" style="display:flex;flex-wrap:wrap;gap:.75em;margin:0 0 1em" role="timer">';
	foreach ( $units as $key => $label ) {
		$html .= '<span style="min-width:4.5em;text-align:center;padding:.5em;border:1px solid rgba(0,0,0,.12);border-radius:4px"><strong data-unit="' . $key . '" style="display:block;font-size:1.6em;line-height:1.2">0</strong><small>' . esc_html( $label ) . '</small></span>';
	}
	$html .= '</div>';

	static $script_done = false;
	if ( ! $script_done ) {
		$script_done = true;
		$html       .= '<script>( function () {
	var pad = function ( n ) { return n < 10 ? "0" + n : String( n ); };
	var tick = function () {
		document.querySelectorAll( ".perfectpixel-countdown[data-end]" ).forEach( function ( box ) {
			var left = Math.max( 0, Math.floor( ( parseInt( box.getAttribute( "data-end" ), 10 ) - Date.now() ) / 1000 ) );
			if ( left <= 0 ) {
				box.textContent = box.getAttribute( "data-expired" );
				box.removeAttribute( "data-end" );
				return;
			}
			var parts = { d: Math.floor( left / 86400 ), h: Math.floor( left % 86400 / 3600 ), m: Math.floor( left % 3600 / 60 ), s: left % 60 };
			box.querySelectorAll( "[data-unit]" ).forEach( function ( el ) {
				var key = el.getAttribute( "data-unit" );
				el.textContent = "d" === key ? String( parts[ key ] ) : pad( parts[ key ] );
			} );
		} );
	};
	var start = function () { tick(); setInterval( tick, 1000 ); };
	if ( "loading" === document.readyState ) { document.addEventListener( "DOMContentLoaded", start ); } else { start(); }
} )();</script>';
	}
	return $html;
}
